<?php
declare(strict_types=1);require_once __DIR__.'/../business/config/public_store_step23.php';$error=null;$catalog=[];$settings=[];try{$pdo=ps23_db();ps23_ensure($pdo);$ctx=ps23_context($pdo);$settings=ps23_settings($pdo,$ctx['organization_id']);foreach(ps23_catalog($pdo,$ctx['organization_id']) as$r)$catalog[(int)$r['id']]=['id'=>(int)$r['id'],'name'=>$r['product_name'],'sku'=>$r['sku'],'mrp'=>(float)$r['mrp'],'vp'=>(float)$r['volume_points'],'category'=>strtoupper((string)$r['category_name']),'availability'=>$r['availability_status']];}catch(Throwable$e){$error=$e->getMessage();}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout Request - Healthcare Wellness Club</title><link rel="stylesheet" href="store.css"></head><body><header class="store-top"><div class="store-bar"><a class="store-brand" href="index.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>Order Request Checkout</small></span></a><div class="store-actions"><a class="store-btn" href="cart.php">Back to Cart</a><a class="store-btn primary" href="index.php">Products</a></div></div></header><main class="store-shell"><section class="store-hero"><div class="store-kicker">SECURE ORDER REQUEST</div><h1>Send your cart to the club for final confirmation.</h1><p>This is not an instant paid checkout. Current MRP/VP is recalculated by the server; the club confirms availability, any eligible pricing, taxes, delivery and payment separately.</p></section><?php if($error):?><div class="notice bad"><?=ps23_h($error)?></div><?php endif;?><section class="two-col" style="margin-top:16px"><article class="card"><h2>Your details</h2><form id="checkoutForm" method="post" action="submit.php"><input type="hidden" name="cart_json" id="cart_json"><input type="hidden" name="started_at" id="started_at"><div style="position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><div class="checkout-grid"><label>Name<input class="store-input" name="name" maxlength="190" autocomplete="name" required></label><label>Mobile<input class="store-input" name="mobile" maxlength="40" autocomplete="tel" required></label><label class="full">Email (optional)<input class="store-input" type="email" name="email" maxlength="190" autocomplete="email"></label><label>Delivery mode<select class="store-select" name="delivery_mode" id="delivery_mode"><option value="club_pickup">Club Pickup</option><option value="home_delivery">Home Delivery / Ecom Drop Point</option></select></label><label>Postal code (optional)<input class="store-input" name="postal_code" maxlength="20" autocomplete="postal-code"></label><label class="full" id="addressLabel" style="display:none">Delivery address<textarea class="store-textarea" name="address" id="address" rows="3" maxlength="1500" autocomplete="street-address"></textarea></label><label class="full">Note (optional)<textarea class="store-textarea" name="note" rows="3" maxlength="2000" placeholder="Product/order note only. Do not send private medical records."></textarea></label><label class="full" style="display:flex;gap:10px;align-items:flex-start"><input type="checkbox" name="consent" value="1" required style="margin-top:5px"><span>I agree that Healthcare Wellness Club may contact me about this product order request.</span></label></div><div id="formAlert"></div><button class="store-btn primary" id="submitBtn" style="width:100%;margin-top:12px">Send Order Request</button></form></article><aside class="card"><h2>Server-verified preview</h2><div id="checkoutItems"></div><div class="summary-line"><span>MRP Total</span><strong id="mrp">₹0.00</strong></div><div class="summary-line"><span>Total VP</span><strong id="vp">0</strong></div><div class="summary-line"><span>Delivery</span><strong id="delivery">₹0.00</strong></div><div class="summary-line grand"><span>Estimated Total</span><strong id="grand">₹0.00</strong></div><div class="notice warn">₹100 delivery charge excluding taxes is shown for applicable nutrition delivery requests below 100 VP. Tax is not calculated in this portal.</div><div class="notice">Payment mode: <b><?=ps23_h(strtoupper((string)($settings['payment_mode']??'review_only')))?></b>. No online payment is collected now.</div></aside></section></main><footer class="store-footer">Your request becomes a final sale only after Business OS review.</footer><script src="store.js"></script><script>const catalog=<?=json_encode($catalog,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;const form=document.getElementById('checkoutForm');const mode=document.getElementById('delivery_mode');const money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(v);function preview(){const cart=hwcCart();document.getElementById('cart_json').value=JSON.stringify(cart);let mrp=0,vp=0,hasNutrition=false;const box=document.getElementById('checkoutItems');box.innerHTML='';for(const row of cart){const p=catalog[Number(row.product_id)];if(!p)continue;const qty=Math.max(1,Math.min(20,Number(row.qty)||1));mrp+=p.mrp*qty;vp+=p.vp*qty;if(!['ART OF PROMOTION','APPLICATIONS'].includes(p.category))hasNutrition=true;const d=document.createElement('div');d.className='summary-line';d.innerHTML=`<span>${qty} × ${esc(p.name)}</span><strong>${money(p.mrp*qty)}</strong>`;box.appendChild(d)}const delivery=mode.value==='home_delivery'&&hasNutrition&&vp>0&&vp<100?100:0;document.getElementById('mrp').textContent=money(mrp);document.getElementById('vp').textContent=vp.toFixed(3).replace(/0+$/,'').replace(/\.$/,'');document.getElementById('delivery').textContent=money(delivery);document.getElementById('grand').textContent=money(mrp+delivery);document.getElementById('addressLabel').style.display=mode.value==='home_delivery'?'block':'none';document.getElementById('address').required=mode.value==='home_delivery';return cart.length>0}function esc(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}mode.addEventListener('change',preview);document.getElementById('started_at').value=String(Date.now());preview();form.addEventListener('submit',async e=>{e.preventDefault();if(!preview()){document.getElementById('formAlert').innerHTML='<div class="notice bad">Your cart is empty.</div>';return}if(!form.reportValidity())return;const btn=document.getElementById('submitBtn');btn.disabled=true;btn.textContent='Submitting…';try{const res=await fetch('submit.php',{method:'POST',body:new FormData(form),headers:{Accept:'application/json'}});const data=await res.json().catch(()=>({}));if(!res.ok||!data.ok)throw new Error(data.message||'Order request could not be submitted.');if(!data.order_code||!data.status_token){document.getElementById('formAlert').innerHTML='<div class="notice">Thanks. Your request has been received.</div>';hwcClear();return}hwcClear();const f=document.createElement('form');f.method='post';f.action='status.php';for(const [k,v] of Object.entries({code:data.order_code,token:data.status_token,created:'1'})){const i=document.createElement('input');i.type='hidden';i.name=k;i.value=v;f.appendChild(i)}document.body.appendChild(f);f.submit()}catch(err){document.getElementById('formAlert').innerHTML='<div class="notice bad">'+esc(err.message||'Something went wrong.')+'</div>'}finally{btn.disabled=false;btn.textContent='Send Order Request'}});</script></body></html>